/// echo suppression for Editable.text: programmatic sets do not reach listeners, native edits do.
#[test]
fn echo_editable_text() {
    on_gtk(|| {
        let mut h = Harness::new();
        let e = h.create("entry");
        h.listen(e, "changed", true).unwrap();
        h.listen(e, "notify::text", true).unwrap();
        h.set_str(e, "text", "from-js").unwrap();
        assert!(h.take_events().is_empty(), "programmatic set is suppressed");
        let o = h.obj(e);
        let v = "from-native";
        o.dynamic_cast_ref::<gtk::Editable>().unwrap().set_text(v);
        let mut got: Vec<String> = h.take_events().into_iter().map(|(_, s)| s).collect();
        got.sort();
        got.dedup();
        let mut want: Vec<String> = ["changed", "notify::text"].iter().map(|s| s.to_string()).collect();
        want.sort();
        assert_eq!(got, want, "native edit still delivers");
        h.set_str(e, "text", "from-js").unwrap();
        assert!(h.take_events().is_empty(), "handlers are unblocked after a programmatic set");
    });
}

